# constructors alternate build 1 / 0 (and 2, any non-zero value) over objects whose vbptrs are preset for build 0.
_O = [(f"$o{i}",) for i in range(6)]
_OB = [("$o0", 1), ("$o1", 0), ("$o2", 1), ("$o3", 0), ("$o4", 2), ("$o5", 0)]
_CT_ARENA = 0x8000
for _name, _addr, _fx, _vec in (("Button::ctor", 0x00488500, "Button", _O), ("ctorObj4a13f0", 0x004A13F0, "ButtonObj", _O),
                                ("viewFieldCtor49d5a0", 0x0049D5A0, "Field49d5a0", _OB),
                                ("viewFieldCtor49ebb0", 0x0049EBB0, "Field49ebb0", _OB),
                                ("panelSubCtor4a3110", 0x004A3110, "PanelSub", _OB),
                                ("viewCtor4a0740", 0x004A0740, "Composite", _OB)):
    for _s in range(3):
        HOOKS[f"{_name}_s{_s}"] = _h(_addr, f"c3ef_ctor_{_fx}_{_s}", _vec, _CT_ARENA, ret="pointer",
                                     args=("pointer",) if _vec is _O else ("pointer", "int"))

